import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import Button from '../components/Button';
import ProgressBar from '../components/ProgressBar';

export default function RoadmapPage() {
  const { name } = useParams();
  const navigate = useNavigate();

  const [roadmapPlan, setRoadmapPlan] = useState([]);
  const [domain, setDomain] = useState('');
  const [timeline, setTimeline] = useState('');

  useEffect(() => {
    const rawPlan = localStorage.getItem('roadmapPlan');
    const selectedDomain = localStorage.getItem('selectedDomain') || name || 'blockchain';
    const savedTimeline = localStorage.getItem('timeline') || '3 months';

    if (rawPlan) {
      try {
        const parsedPlan = JSON.parse(rawPlan);
        if (Array.isArray(parsedPlan)) {
          setRoadmapPlan(parsedPlan);
        }
      } catch (e) {
        console.error("Local storage parsing error", e);
      }
    }

    setDomain(selectedDomain);
    setTimeline(savedTimeline);
  }, [name]);

  const handleStartLearning = () => navigate('/tasks');

  const getDomainTitle = () =>
    domain.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');

  const completedDays = JSON.parse(localStorage.getItem("completedDays") || "[]");

  // ✅ Dynamic tasks per day
  const TASKS_PER_DAY = parseInt(localStorage.getItem("tasksPerDay")) || 3;

  // ✅ Total tasks
  const totalTasks = Array.isArray(roadmapPlan)
    ? roadmapPlan.reduce((sum, phase) => sum + phase.length, 0)
    : 0;

  // ✅ Total days (FIXED)
  const totalDays = Math.ceil(totalTasks / TASKS_PER_DAY);

  const completedCount = completedDays.length;
  const remainingDays = Math.max(totalDays - completedCount, 0);

  const completionPercentage =
    totalDays > 0
      ? Math.min(100, Math.round((completedCount / totalDays) * 100))
      : 0;

  const getPhaseProgress = (phaseIndex, phaseTasks) => {
    let tasksBefore = 0;

    for (let i = 0; i < phaseIndex; i++) {
      if (roadmapPlan[i]) tasksBefore += roadmapPlan[i].length;
    }

    const phaseStartDay = Math.floor(tasksBefore / TASKS_PER_DAY) + 1;
    const phaseTotalDays = Math.ceil(phaseTasks.length / TASKS_PER_DAY);

    let completedInPhase = completedDays.filter(
      (day) =>
        day >= phaseStartDay &&
        day < phaseStartDay + phaseTotalDays
    ).length;

    return Math.min(
      100,
      Math.round((completedInPhase / phaseTotalDays) * 100)
    );
  };

  const getCurrentPhaseIndex = () => {
    let tasksCovered = completedDays.length * TASKS_PER_DAY;
    let cumulativeTasks = 0;

    for (let i = 0; i < roadmapPlan.length; i++) {
      cumulativeTasks += roadmapPlan[i].length;
      if (tasksCovered < cumulativeTasks) return i;
    }

    return Math.max(0, roadmapPlan.length - 1);
  };

  const currentPhaseIndex = getCurrentPhaseIndex();

  const isPhaseCompleted = (phaseIndex, phaseTasks) =>
    getPhaseProgress(phaseIndex, phaseTasks) === 100;

  return (
    <div className="space-y-8">
      {/* Header */}
      <div className="rounded-[2rem] border bg-gradient-to-br from-white to-blue-50 p-8 shadow-lg">
        <h1 className="text-4xl font-bold">{getDomainTitle()} Roadmap</h1>
        <p className="mt-3 text-lg text-slate-600">
          Your personalized {timeline} learning path with {roadmapPlan.length} phases
        </p>

        <div className="mt-6 flex flex-col gap-6 lg:flex-row">
          <div className="flex-1">
            <p className="text-sm font-medium">Overall Progress</p>
            <ProgressBar label="Roadmap" value={completionPercentage} />
          </div>

          <div className="rounded-3xl bg-teal-100 p-5">
            <p className="text-sm">Timeline</p>
            <p className="text-2xl font-bold">{timeline}</p>
          </div>

          <div className="rounded-3xl bg-orange-100 p-5">
            <p className="text-sm">Days Remaining</p>
            <p className="text-2xl font-bold">
              {remainingDays} / {totalDays}
            </p>
          </div>
        </div>
      </div>

      {/* Phases */}
      <div className="rounded-[2rem] border bg-white p-8 shadow-lg">
        <h2 className="text-2xl font-semibold mb-6">📚 Learning Phases</h2>

        {roadmapPlan.length === 0 ? (
          <div className="text-center py-10 text-slate-500">
            No phases generated.
          </div>
        ) : (
          <div className="space-y-6">
            {roadmapPlan.map((phase, index) => (
              <div key={index} className="rounded-3xl border p-6">
                <h3 className="font-bold mb-4">
                  Phase {index + 1}
                </h3>

                <ProgressBar
                  label="Phase Progress"
                  value={getPhaseProgress(index, phase)}
                />

                <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4 mt-4">
                  {phase.slice(0, 4).map((task, tIdx) => (
                    <div key={tIdx} className="p-4 border rounded-xl">
                      {task}
                    </div>
                  ))}
                </div>

                {phase.length > 4 && (
                  <p className="mt-2 text-xs">
                    + {phase.length - 4} more tasks
                  </p>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="flex justify-center pb-10">
        <Button onClick={handleStartLearning}>
          Start Learning 🚀
        </Button>
      </div>
    </div>
  );
}
